const creationLabel = (value?:string|null) => { if(!value)return "—"; const date=new Date(value);return Number.isNaN(date.getTime())?"—":new Intl.DateTimeFormat("it-IT",{day:"numeric",month:"short",timeZone:"Europe/Rome"}).format(date).replace(/\.$/,"").replace(/ (\p{L}+)$/u,(_,month:string)=>` ${month.slice(0,3).toLowerCase()}.`); };
