  const [project,setProject]=useState("Tutte le aree"), [status,setStatus]=useState<(typeof statuses)[number]>("Tutte"), [query,setQuery]=useState(""), [priorityFilter,setPriorityFilter]=useState<(typeof priorities)[number]>("Tutte"),[createdSort,setCreatedSort]=useState<"recent"|"oldest">("recent"),[selectedAggregateAreas,setSelectedAggregateAreas]=useState<string[]>([]);
