  const projects=useMemo(()=>{const rank=(n:string)=>{const i=areaOrder.indexOf(n);return i<0?Number.MAX_SAFE_INTEGER:i};return allProjects.filter(p=>!areaSettings[p]?.archived).sort((a,b)=>Number(!!areaSettings[b]?.pinned)-Number(!!areaSettings[a]?.pinned)||rank(a)-rank(b)||a.localeCompare(b,"it"))},[allProjects,areaSettings,areaOrder]);
  const archivedProjects=allProjects.filter(p=>areaSettings[p]?.archived);
  const unassignedAreas=projects.filter(area=>!todlyProjects.some(p=>(p.areaNames??[]).includes(area)));
